    # Find connected foreground components within each panel.
    def components(rows, cols):
        seen = set()
        result = []
        for r in rows:
            for c in cols:
                color = grid[r][c]
                if color == 0 or color == sep_color or (r, c) in seen:
                    continue
                q = deque([(r, c)])
                seen.add((r, c))
                cells = []
                while q:
                    rr, cc = q.popleft()
