                rs = [r for r, c in cells]
                cs = [c for r, c in cells]
                r0, c0 = min(rs), min(cs)
                shape = {(r-r0, c-c0) for r, c in cells}
                rh, cw = max(rs)-r0+1, max(cs)-c0+1
                if rh == 2 and cw == 2 and len(cells) == 4:
